export type ParsedResolveAppealInstruction<
  TProgram extends string = typeof ESCROW_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    payer: TAccountMetas[0];
    /** Must be the bet's snapshotted `appeal_authority` (I8, I11). */
    appealAuthority: TAccountMetas[1];
    bet: TAccountMetas[2];
    vault: TAccountMetas[3];
    mint: TAccountMetas[4];
    /** Required iff `to_a > 0`. SPL owner field == `bet.party_a` (I1, TM-F1/F4). */
    partyAToken?: TAccountMetas[5] | undefined;
    /** Required iff `to_b > 0`. SPL owner field == `bet.party_b`. */
    partyBToken?: TAccountMetas[6] | undefined;
    tokenProgram: TAccountMetas[7];
    eventAuthority: TAccountMetas[8];
    program: TAccountMetas[9];
  };
  data: ResolveAppealInstructionData;
};

export function parseResolveAppealInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedResolveAppealInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 10,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === ESCROW_PROGRAM_ADDRESS ? undefined : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      appealAuthority: getNextAccount(),
      bet: getNextAccount(),
      vault: getNextAccount(),
      mint: getNextAccount(),
      partyAToken: getNextOptionalAccount(),
      partyBToken: getNextOptionalAccount(),
      tokenProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getResolveAppealInstructionDataDecoder().decode(instruction.data),
  };
}
